ui.debug.addRules("radiance",[{rules:"Place mirrors (/ or \\) on each gray diamond to guide the beam from the emitter to the target.\n1. The dark square with an arrow is the emitter. It fires a beam in the arrow direction.\n2. The red bullseye is the target. The beam must reach it.\n3. Gray diamonds are mirror slots. Place / or \\ on each one.\n4. Forward slash (/) reflects the beam: UP becomes RIGHT, RIGHT becomes UP, DOWN becomes LEFT, LEFT becomes DOWN.\n5. Backslash (\\) reflects the beam: UP becomes LEFT, LEFT becomes UP, DOWN becomes RIGHT, RIGHT becomes DOWN.\n6. The beam must pass through ALL mirror slots on its way to the target. No slot may be skipped.",history:"This genre was created as an original puzzle for ppbench."},{rules:"灰色のひし形にミラー（/または\\）を置いて、エミッターからターゲットまでビームを導きましょう。\n1. 矢印付きの黒いマスがエミッターです。矢印の方向にビームを発射します。\n2. 赤い的がターゲットです。ビームはここに到達しなければなりません。\n3. 灰色のひし形はミラースロットです。それぞれに/か\\を置きます。\n4. /（スラッシュ）は上↔右、下↔左にビームを反射します。\n5. \\（バックスラッシュ）は上↔左、下↔右にビームを反射します。\n6. ビームはすべてのミラースロットを通らなければなりません。",history:"ppbenchオリジナルパズル"}]),ui.debug.addDebugData("radiance",{url:"6/6/14d3l2d3l",failcheck:[["rdMissedTarget","pzprv3/radiance/6/6/E4 . . . . S /. . . . . . /. . . . . . /T . . . . S /. . . . . . /. . . . . . /"],["rdMissedTarget","pzprv3/radiance/6/6/E4 . . . . 2 /. . . . . . /. . . . . . /T . . . . S /. . . . . . /. . . . . . /"],[null,"pzprv3/radiance/6/6/E4 . . . . 2 /. . . . . . /. . . . . . /T . . . . 1 /. . . . . . /. . . . . . /"]]});
